CREATE TABLE access_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), started_by uuid NOT NULL, status varchar(20) NOT NULL DEFAULT 'open', period_start timestamptz NOT NULL, period_end timestamptz, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, CONSTRAINT access_reviews_starter_fk FOREIGN KEY(tenant_id,started_by) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE access_review_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), review_id uuid NOT NULL REFERENCES access_reviews(id) ON DELETE CASCADE, membership_id uuid NOT NULL, reviewer_id uuid NOT NULL, decision varchar(20) NOT NULL CHECK(decision IN ('approve','revoke','remediate')), reason varchar(1000), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT access_review_member_fk FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id), CONSTRAINT access_review_reviewer_fk FOREIGN KEY(tenant_id,reviewer_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE compliance_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), requested_by uuid NOT NULL, report_type varchar(60) NOT NULL, parameters jsonb NOT NULL DEFAULT '{}'::jsonb, status varchar(20) NOT NULL DEFAULT 'ready', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, CONSTRAINT compliance_reports_requester_fk FOREIGN KEY(tenant_id,requested_by) REFERENCES tenant_memberships(tenant_id,id));
